(async()=>{try{const r=await fetch('./app.js.gz.b64',{cache:'no-store'});if(!r.ok)throw new Error('app source');const encoded=(await r.text()).trim(),bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));if(typeof DecompressionStream!=='function')throw new Error('browser unsupported');const stream=new DecompressionStream('gzip'),js=await new Response(new Blob([bytes]).stream().pipeThrough(stream)).text(),app=document.createElement('script');app.textContent=js;document.head.appendChild(app);const seed=document.createElement('script');seed.src='./seed-fukuoka.js';seed.onload=()=>setTimeout(()=>{const brand=document.querySelector('#brandTrip');if(brand)brand.textContent='福岡自由行｜本機復原模式';const sync=document.querySelector('#syncText');if(sync)sync.textContent='本機已儲存';const dot=document.querySelector('#syncDot');if(dot)dot.classList.add('ok');document.querySelectorAll('.notice').forEach(el=>{if(el.textContent.includes('共用雲端'))el.textContent='儲存後會保存在目前裝置。其他手機可使用 JSON 備份轉移最新資料。'});const rows=document.querySelectorAll('.settings-row p');if(rows[0])rows[0].textContent='重新讀取目前裝置已加密保存的資料。';},900);document.body.appendChild(seed)}catch(e){console.error(e);document.body.innerHTML='<main style="font-family:-apple-system;padding:32px"><h2>暫時未能載入旅程</h2><p>請重新整理頁面。</p></main>'}})();